// Transform DRCT order creation response to Aviaframe format
const response = $input.item.json;

console.log('[Transform] DRCT order creation response received');

const segments = Array.isArray(response.flights)
  ? response.flights.flatMap((flight) =>
      Array.isArray(flight.segments)
        ? flight.segments.map((segment) => ({
            id: segment.id || null,
            origin: segment.departure_airport?.code || segment.departure_city?.code || null,
            origin_name: segment.departure_airport?.name || segment.departure_city?.name || null,
            destination: segment.arrival_airport?.code || segment.arrival_city?.code || null,
            destination_name: segment.arrival_airport?.name || segment.arrival_city?.name || null,
            departure: segment.departure_date && segment.departure_time
              ? `${segment.departure_date} ${segment.departure_time}`
              : null,
            arrival: segment.arrival_date && segment.arrival_time
              ? `${segment.arrival_date} ${segment.arrival_time}`
              : null,
            carrier: segment.carrier?.airline_code || null,
            airline_name: segment.carrier?.airline_name || null,
            flight_number: segment.flight_number || null,
            aircraft: segment.aircraft || null,
            duration: Number(segment.duration || 0),
            status: segment.status || null
          }))
        : []
    )
  : [];

const perPassenger = Array.isArray(response.price_details)
  ? response.price_details.map((item) => ({
      type: item.type || null,
      count: Number(item.count || 0),
      total: Number(item.price?.amount || item.price?.total || 0),
      currency: item.price?.currency || response.price?.currency || 'USD',
      fare: Number(item.fare?.amount || item.fare?.total || 0),
      taxes: Number(item.taxes?.amount || item.taxes?.total || 0)
    }))
  : [];

return {
  order_id: response.order_id || response.id,
  status: String(response.status || 'CREATED').toUpperCase(),
  pnr: response.pnr || response.locator || response.airline_locators?.[0]?.locator || null,
  locator: response.locator || null,
  airline_locators: response.airline_locators || [],
  price: {
    total: Number(response.price?.amount || response.price?.total || 0),
    currency: response.price?.currency || 'USD',
    breakdown: {
      base_fare: Number(response.price_details?.[0]?.fare?.amount || 0),
      taxes: Number(response.price_details?.[0]?.taxes?.amount || 0),
      fees: Number(response.price?.fees || 0),
      surcharges: Number(response.price?.surcharges || 0)
    },
    per_passenger: perPassenger
  },
  passengers: response.passengers || [],
  segments,
  fares: response.fares || [],
  tickets: response.tickets || [],
  payment: {
    method: response.payment?.method || 'CARD',
    status: response.payment?.status || 'PENDING',
    deadline: response.payment?.deadline || response.cancel_before || null
  },
  created_at: response.created_at || new Date().toISOString(),
  expires_at: response.expires_at || response.cancel_before || null,
  metadata: {
    processed_at: new Date().toISOString(),
    workflow_id: 'drct_order_create',
    channel: response.channel || null
  }
};

